// ─── Domain Models ────────────────────────────────────────────────────────────

export interface User {
  id: string;
  name: string;
  email: string;
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO timestamp
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO timestamp
}

// ─── Event Payloads ───────────────────────────────────────────────────────────

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
  projectId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  projectId: string;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  assigneeId: string | null;
  body: string;
}

export interface TaskCreatedPayload {
  taskId: string;
  taskTitle: string;
  projectId: string;
}

export interface MemberAddedPayload {
  projectId: string;
  projectName: string;
  userId: string;
}

// ─── Event Map ────────────────────────────────────────────────────────────────

export interface EventMap {
  "task.assigned": TaskAssignedPayload;
  "task.statusChanged": TaskStatusChangedPayload;
  "task.created": TaskCreatedPayload;
  "comment.added": CommentAddedPayload;
  "member.added": MemberAddedPayload;
}

export type EventName = keyof EventMap;

// ─── HTTP Helpers ─────────────────────────────────────────────────────────────

export interface ApiRequest {
  method: string;
  path: string;
  params: Record<string, string>;
  query: Record<string, string>;
  body: unknown;
}

export interface ApiResponse {
  status: number;
  body: unknown;
}

import { EventMap, EventName } from "./types";

// A typed subscriber callback for a given event name
type Subscriber<K extends EventName> = (payload: EventMap[K]) => void;

/**
 * EventBus — a simple in-memory publish/subscribe system.
 *
 * Services publish named events with a typed payload. Any number of other
 * services may subscribe to those events and will be called synchronously
 * when the event is published.
 */
export class EventBus {
  // We store subscribers as a map from event name → array of callbacks.
  // The `any` here is intentional: we enforce type safety through the
  // publish / subscribe generics at the call site.
  private subscribers: Map<string, Array<(payload: unknown) => void>> =
    new Map();

  /**
   * Subscribe to an event.  The callback receives the strongly-typed payload
   * for that event name.
   */
  subscribe<K extends EventName>(event: K, callback: Subscriber<K>): void {
    const list = this.subscribers.get(event) ?? [];
    list.push(callback as (payload: unknown) => void);
    this.subscribers.set(event, list);
  }

  /**
   * Publish an event.  All subscribers registered for `event` are called
   * synchronously in the order they subscribed.
   */
  publish<K extends EventName>(event: K, payload: EventMap[K]): void {
    const list = this.subscribers.get(event) ?? [];
    for (const cb of list) {
      cb(payload);
    }
  }
}

import { randomUUID } from "crypto";
import { User } from "./types";

/**
 * UserService — owns all user data.
 *
 * No other service should read from or write to this store directly.
 * If another part of the system needs to verify a user exists it should
 * call the public methods exposed here via the router orchestration layer.
 */
export class UserService {
  private users: Map<string, User> = new Map();

  // ── CRUD ──────────────────────────────────────────────────────────────────

  createUser(data: { name: string; email: string }): User {
    if (!data.name || !data.email) {
      throw new Error("name and email are required");
    }

    // Guard against duplicate emails
    for (const u of this.users.values()) {
      if (u.email === data.email) {
        throw new Error(`A user with email "${data.email}" already exists`);
      }
    }

    const user: User = {
      id: randomUUID(),
      name: data.name,
      email: data.email,
    };

    this.users.set(user.id, user);
    return user;
  }

  getUser(id: string): User {
    const user = this.users.get(id);
    if (!user) throw new Error(`User "${id}" not found`);
    return user;
  }

  getAllUsers(): User[] {
    return Array.from(this.users.values());
  }

  updateUser(id: string, data: Partial<{ name: string; email: string }>): User {
    const user = this.getUser(id);

    // Guard against duplicate emails when changing email
    if (data.email && data.email !== user.email) {
      for (const u of this.users.values()) {
        if (u.email === data.email) {
          throw new Error(`A user with email "${data.email}" already exists`);
        }
      }
    }

    const updated: User = {
      ...user,
      ...(data.name !== undefined ? { name: data.name } : {}),
      ...(data.email !== undefined ? { email: data.email } : {}),
    };

    this.users.set(id, updated);
    return updated;
  }

  deleteUser(id: string): void {
    if (!this.users.has(id)) throw new Error(`User "${id}" not found`);
    this.users.delete(id);
  }

  /** Convenience: returns true if a user with this id exists. */
  exists(id: string): boolean {
    return this.users.has(id);
  }
}

import { randomUUID } from "crypto";
import { EventBus } from "./event-bus";
import { Project } from "./types";

/**
 * ProjectService — owns all project data.
 *
 * Publishes:
 *   • member.added   — when a user is added to a project
 */
export class ProjectService {
  private projects: Map<string, Project> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  // ── CRUD ──────────────────────────────────────────────────────────────────

  createProject(data: { name: string; description: string }): Project {
    if (!data.name) throw new Error("name is required");

    const project: Project = {
      id: randomUUID(),
      name: data.name,
      description: data.description ?? "",
      memberIds: [],
    };

    this.projects.set(project.id, project);
    return project;
  }

  getProject(id: string): Project {
    const project = this.projects.get(id);
    if (!project) throw new Error(`Project "${id}" not found`);
    return project;
  }

  getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  updateProject(
    id: string,
    data: Partial<{ name: string; description: string }>
  ): Project {
    const project = this.getProject(id);

    const updated: Project = {
      ...project,
      ...(data.name !== undefined ? { name: data.name } : {}),
      ...(data.description !== undefined
        ? { description: data.description }
        : {}),
    };

    this.projects.set(id, updated);
    return updated;
  }

  deleteProject(id: string): void {
    if (!this.projects.has(id)) throw new Error(`Project "${id}" not found`);
    this.projects.delete(id);
  }

  // ── Member Management ─────────────────────────────────────────────────────

  addMember(projectId: string, userId: string): Project {
    const project = this.getProject(projectId);

    if (project.memberIds.includes(userId)) {
      throw new Error(
        `User "${userId}" is already a member of project "${projectId}"`
      );
    }

    const updated: Project = {
      ...project,
      memberIds: [...project.memberIds, userId],
    };

    this.projects.set(projectId, updated);

    this.eventBus.publish("member.added", {
      projectId,
      projectName: updated.name,
      userId,
    });

    return updated;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getProject(projectId);

    if (!project.memberIds.includes(userId)) {
      throw new Error(
        `User "${userId}" is not a member of project "${projectId}"`
      );
    }

    const updated: Project = {
      ...project,
      memberIds: project.memberIds.filter((id) => id !== userId),
    };

    this.projects.set(projectId, updated);
    return updated;
  }

  /** Convenience: returns true if a project with this id exists. */
  exists(id: string): boolean {
    return this.projects.has(id);
  }
}

import { randomUUID } from "crypto";
import { EventBus } from "./event-bus";
import { Task, TaskStatus } from "./types";

// Valid forward-only status transitions
const TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ["in-progress"],
  "in-progress": ["done"],
  done: [],
};

/**
 * TaskService — owns all task data.
 *
 * Publishes:
 *   • task.created       — when a task is first created
 *   • task.assigned      — when a task is (re-)assigned to a user
 *   • task.statusChanged — when a task's status changes
 */
export class TaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  // ── CRUD ──────────────────────────────────────────────────────────────────

  createTask(data: {
    title: string;
    description?: string;
    projectId: string;
    assigneeId?: string | null;
  }): Task {
    if (!data.title) throw new Error("title is required");
    if (!data.projectId) throw new Error("projectId is required");

    const task: Task = {
      id: randomUUID(),
      title: data.title,
      description: data.description ?? "",
      status: "todo",
      assigneeId: data.assigneeId ?? null,
      projectId: data.projectId,
    };

    this.tasks.set(task.id, task);

    this.eventBus.publish("task.created", {
      taskId: task.id,
      taskTitle: task.title,
      projectId: task.projectId,
    });

    // If created with an assignee, also fire task.assigned
    if (task.assigneeId) {
      this.eventBus.publish("task.assigned", {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: task.assigneeId,
        projectId: task.projectId,
      });
    }

    return task;
  }

  getTask(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) throw new Error(`Task "${id}" not found`);
    return task;
  }

  getTasksByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  getAllTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  updateTask(
    id: string,
    data: Partial<{ title: string; description: string }>
  ): Task {
    const task = this.getTask(id);

    const updated: Task = {
      ...task,
      ...(data.title !== undefined ? { title: data.title } : {}),
      ...(data.description !== undefined
        ? { description: data.description }
        : {}),
    };

    this.tasks.set(id, updated);
    return updated;
  }

  deleteTask(id: string): void {
    if (!this.tasks.has(id)) throw new Error(`Task "${id}" not found`);
    this.tasks.delete(id);
  }

  // ── Status Transitions ────────────────────────────────────────────────────

  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.getTask(id);

    if (task.status === newStatus) return task; // idempotent — no event

    const allowed = TRANSITIONS[task.status];
    if (!allowed.includes(newStatus)) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". ` +
          `Allowed next statuses: ${allowed.length ? allowed.join(", ") : "none"}`
      );
    }

    const oldStatus = task.status;
    const updated: Task = { ...task, status: newStatus };
    this.tasks.set(id, updated);

    this.eventBus.publish("task.statusChanged", {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId: updated.assigneeId,
      projectId: updated.projectId,
      oldStatus,
      newStatus,
    });

    return updated;
  }

  // ── Assignment ────────────────────────────────────────────────────────────

  assignTask(id: string, assigneeId: string): Task {
    const task = this.getTask(id);

    const updated: Task = { ...task, assigneeId };
    this.tasks.set(id, updated);

    this.eventBus.publish("task.assigned", {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId,
      projectId: updated.projectId,
    });

    return updated;
  }

  /** Convenience: returns true if a task with this id exists. */
  exists(id: string): boolean {
    return this.tasks.has(id);
  }
}

import { randomUUID } from "crypto";
import { EventBus } from "./event-bus";
import { Comment } from "./types";

/**
 * CommentService — owns all comment data.
 *
 * Publishes:
 *   • comment.added — when a comment is created
 *
 * The service expects the caller (router) to supply the task's current
 * title and assigneeId so that the event payload is fully self-contained
 * without requiring a direct call to the TaskService.
 */
export class CommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  // ── CRUD ──────────────────────────────────────────────────────────────────

  /**
   * Creates a comment.
   *
   * @param taskTitle   – title of the parent task (for the event payload)
   * @param assigneeId  – current assignee of the parent task (may be null)
   */
  createComment(data: {
    taskId: string;
    authorId: string;
    body: string;
    taskTitle: string;
    assigneeId: string | null;
  }): Comment {
    if (!data.taskId) throw new Error("taskId is required");
    if (!data.authorId) throw new Error("authorId is required");
    if (!data.body) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId,
      authorId: data.authorId,
      body: data.body,
      createdAt: new Date().toISOString(),
    };

    this.comments.set(comment.id, comment);

    this.eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: data.taskTitle,
      authorId: comment.authorId,
      assigneeId: data.assigneeId,
      body: comment.body,
    });

    return comment;
  }

  getComment(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) throw new Error(`Comment "${id}" not found`);
    return comment;
  }

  getCommentsByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values())
      .filter((c) => c.taskId === taskId)
      .sort(
        (a, b) =>
          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
      );
  }

  deleteComment(id: string): void {
    if (!this.comments.has(id)) throw new Error(`Comment "${id}" not found`);
    this.comments.delete(id);
  }

  /** Delete all comments belonging to a task (e.g. when a task is deleted). */
  deleteCommentsByTask(taskId: string): void {
    for (const [id, comment] of this.comments) {
      if (comment.taskId === taskId) {
        this.comments.delete(id);
      }
    }
  }
}

import { randomUUID } from "crypto";
import { EventBus } from "./event-bus";
import { Notification } from "./types";

/**
 * NotificationService — owns all notification data.
 *
 * Subscribes to:
 *   • task.assigned      → notifies the new assignee
 *   • task.statusChanged → notifies the assignee (if any) of the status change
 *   • comment.added      → notifies the task's assignee (if different from author)
 *   • member.added       → notifies the user that they joined a project
 *
 * All subscriptions are wired up in the constructor.
 */
export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(eventBus: EventBus) {
    // ── Subscribe to events ──────────────────────────────────────────────────

    eventBus.subscribe("task.assigned", (payload) => {
      this.createNotification(
        payload.assigneeId,
        `You have been assigned to task "${payload.taskTitle}"`
      );
    });

    eventBus.subscribe("task.statusChanged", (payload) => {
      if (payload.assigneeId) {
        this.createNotification(
          payload.assigneeId,
          `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}"`
        );
      }
    });

    eventBus.subscribe("comment.added", (payload) => {
      // Notify the assignee only when they are NOT the author of the comment
      if (
        payload.assigneeId &&
        payload.assigneeId !== payload.authorId
      ) {
        this.createNotification(
          payload.assigneeId,
          `New comment on task "${payload.taskTitle}": "${payload.body.slice(0, 80)}${payload.body.length > 80 ? "…" : ""}"`
        );
      }
    });

    eventBus.subscribe("member.added", (payload) => {
      this.createNotification(
        payload.userId,
        `You have been added to project "${payload.projectName}"`
      );
    });
  }

  // ── Public API ─────────────────────────────────────────────────────────────

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };

    this.notifications.set(notification.id, notification);
    return notification;
  }

  getNotificationsForUser(userId: string): Notification[] {
    return Array.from(this.notifications.values())
      .filter((n) => n.userId === userId)
      .sort(
        (a, b) =>
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      );
  }

  getAllNotifications(): Notification[] {
    return Array.from(this.notifications.values()).sort(
      (a, b) =>
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  markAsRead(id: string): Notification {
    const notification = this.notifications.get(id);
    if (!notification) throw new Error(`Notification "${id}" not found`);

    const updated: Notification = { ...notification, read: true };
    this.notifications.set(id, updated);
    return updated;
  }
}

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import { UserService } from "./user-service";
import { ProjectService } from "./project-service";
import { TaskService } from "./task-service";
import { CommentService } from "./comment-service";
import { NotificationService } from "./notification-service";
import { ApiRequest, ApiResponse, TaskStatus } from "./types";

// ── Helper: read the full request body as a string ───────────────────────────

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf-8")));
    req.on("error", reject);
  });
}

// ── Route Matching ────────────────────────────────────────────────────────────

interface RouteMatch {
  params: Record<string, string>;
}

/**
 * A tiny route pattern matcher.
 * Patterns may contain :param segments (e.g. "/users/:id").
 * Returns null when the pattern does not match.
 */
function matchRoute(
  pattern: string,
  pathname: string
): RouteMatch | null {
  const patternParts = pattern.split("/").filter(Boolean);
  const pathParts = pathname.split("/").filter(Boolean);

  if (patternParts.length !== pathParts.length) return null;

  const params: Record<string, string> = {};

  for (let i = 0; i < patternParts.length; i++) {
    const pp = patternParts[i];
    const vp = pathParts[i];

    if (pp.startsWith(":")) {
      params[pp.slice(1)] = decodeURIComponent(vp);
    } else if (pp !== vp) {
      return null;
    }
  }

  return { params };
}

// ── Router ───────────────────────────────────────────────────────────────────

export class Router {
  constructor(
    private readonly userService: UserService,
    private readonly projectService: ProjectService,
    private readonly taskService: TaskService,
    private readonly commentService: CommentService,
    private readonly notificationService: NotificationService
  ) {}

  /** Entry point — called by the HTTP server for every request. */
  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    // Parse URL and query string
    const base = `http://${req.headers.host ?? "localhost"}`;
    const url = new URL(req.url ?? "/", base);
    const pathname = url.pathname.replace(/\/$/, "") || "/";
    const method = (req.method ?? "GET").toUpperCase();

    // Parse query string into a plain object
    const query: Record<string, string> = {};
    url.searchParams.forEach((v, k) => {
      query[k] = v;
    });

    // Parse body (only for methods that may carry one)
    let body: unknown = null;
    if (["POST", "PUT", "PATCH"].includes(method)) {
      const raw = await readBody(req);
      if (raw) {
        try {
          body = JSON.parse(raw);
        } catch {
          this.send(res, { status: 400, body: { error: "Invalid JSON body" } });
          return;
        }
      }
    }

    const apiReq: ApiRequest = { method, path: pathname, params: {}, query, body };

    let apiRes: ApiResponse;

    try {
      apiRes = this.route(apiReq);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Internal server error";
      apiRes = { status: 500, body: { error: message } };
    }

    this.send(res, apiRes);
  }

  // ── Response serialisation ─────────────────────────────────────────────────

  private send(res: ServerResponse, apiRes: ApiResponse): void {
    const json = JSON.stringify(apiRes.body, null, 2);
    res.writeHead(apiRes.status, {
      "Content-Type": "application/json",
      "Content-Length": Buffer.byteLength(json),
    });
    res.end(json);
  }

  // ── Route Dispatch ─────────────────────────────────────────────────────────

  private route(req: ApiRequest): ApiResponse {
    const { method, path } = req;

    // ── Users ──────────────────────────────────────────────────────────────

    if (method === "GET" && path === "/users") {
      return this.listUsers();
    }

    if (method === "POST" && path === "/users") {
      return this.createUser(req);
    }

    {
      const m = matchRoute("/users/:id", path);
      if (m) {
        req.params = m.params;
        if (method === "GET") return this.getUser(req);
        if (method === "PUT") return this.updateUser(req);
        if (method === "DELETE") return this.deleteUser(req);
      }
    }

    // ── Projects ───────────────────────────────────────────────────────────

    if (method === "GET" && path === "/projects") {
      return this.listProjects();
    }

    if (method === "POST" && path === "/projects") {
      return this.createProject(req);
    }

    {
      const m = matchRoute("/projects/:id", path);
      if (m) {
        req.params = m.params;
        if (method === "GET") return this.getProject(req);
        if (method === "PUT") return this.updateProject(req);
        if (method === "DELETE") return this.deleteProject(req);
      }
    }

    {
      const m = matchRoute("/projects/:id/members", path);
      if (m) {
        req.params = m.params;
        if (method === "POST") return this.addMember(req);
        if (method === "DELETE") return this.removeMember(req);
      }
    }

    // ── Tasks ──────────────────────────────────────────────────────────────

    if (method === "GET" && path === "/tasks") {
      return this.listTasks(req);
    }

    if (method === "POST" && path === "/tasks") {
      return this.createTask(req);
    }

    {
      const m = matchRoute("/tasks/:id", path);
      if (m) {
        req.params = m.params;
        if (method === "GET") return this.getTask(req);
        if (method === "PUT") return this.updateTask(req);
        if (method === "DELETE") return this.deleteTask(req);
      }
    }

    {
      const m = matchRoute("/tasks/:id/status", path);
      if (m) {
        req.params = m.params;
        if (method === "PUT") return this.changeTaskStatus(req);
      }
    }

    {
      const m = matchRoute("/tasks/:id/assign", path);
      if (m) {
        req.params = m.params;
        if (method === "PUT") return this.assignTask(req);
      }
    }

    // ── Comments ───────────────────────────────────────────────────────────

    if (method === "GET" && path === "/comments") {
      return this.listComments(req);
    }

    if (method === "POST" && path === "/comments") {
      return this.createComment(req);
    }

    {
      const m = matchRoute("/comments/:id", path);
      if (m) {
        req.params = m.params;
        if (method === "GET") return this.getComment(req);
        if (method === "DELETE") return this.deleteComment(req);
      }
    }

    // ── Notifications ──────────────────────────────────────────────────────

    if (method === "GET" && path === "/notifications") {
      return this.listNotifications(req);
    }

    {
      const m = matchRoute("/notifications/:id/read", path);
      if (m) {
        req.params = m.params;
        if (method === "PUT") return this.markNotificationRead(req);
      }
    }

    // ── 404 ────────────────────────────────────────────────────────────────

    return { status: 404, body: { error: `Cannot ${method} ${path}` } };
  }

  // ── User Handlers ──────────────────────────────────────────────────────────

  private listUsers(): ApiResponse {
    return { status: 200, body: this.userService.getAllUsers() };
  }

  private createUser(req: ApiRequest): ApiResponse {
    const data = req.body as { name?: string; email?: string };
    const user = this.userService.createUser({
      name: data?.name ?? "",
      email: data?.email ?? "",
    });
    return { status: 201, body: user };
  }

  private getUser(req: ApiRequest): ApiResponse {
    const user = this.userService.getUser(req.params.id);
    return { status: 200, body: user };
  }

  private updateUser(req: ApiRequest): ApiResponse {
    const data = req.body as Partial<{ name: string; email: string }>;
    const user = this.userService.updateUser(req.params.id, data ?? {});
    return { status: 200, body: user };
  }

  private deleteUser(req: ApiRequest): ApiResponse {
    this.userService.deleteUser(req.params.id);
    return { status: 200, body: { message: "User deleted" } };
  }

  // ── Project Handlers ───────────────────────────────────────────────────────

  private listProjects(): ApiResponse {
    return { status: 200, body: this.projectService.getAllProjects() };
  }

  private createProject(req: ApiRequest): ApiResponse {
    const data = req.body as { name?: string; description?: string };
    const project = this.projectService.createProject({
      name: data?.name ?? "",
      description: data?.description ?? "",
    });
    return { status: 201, body: project };
  }

  private getProject(req: ApiRequest): ApiResponse {
    const project = this.projectService.getProject(req.params.id);
    return { status: 200, body: project };
  }

  private updateProject(req: ApiRequest): ApiResponse {
    const data = req.body as Partial<{ name: string; description: string }>;
    const project = this.projectService.updateProject(req.params.id, data ?? {});
    return { status: 200, body: project };
  }

  private deleteProject(req: ApiRequest): ApiResponse {
    this.projectService.deleteProject(req.params.id);
    return { status: 200, body: { message: "Project deleted" } };
  }

  private addMember(req: ApiRequest): ApiResponse {
    const data = req.body as { userId?: string };
    const userId = data?.userId;
    if (!userId) {
      return { status: 400, body: { error: "userId is required" } };
    }
    // Validate user exists
    if (!this.userService.exists(userId)) {
      return { status: 404, body: { error: `User "${userId}" not found` } };
    }
    const project = this.projectService.addMember(req.params.id, userId);
    return { status: 200, body: project };
  }

  private removeMember(req: ApiRequest): ApiResponse {
    const data = req.body as { userId?: string };
    const userId = data?.userId;
    if (!userId) {
      return { status: 400, body: { error: "userId is required" } };
    }
    const project = this.projectService.removeMember(req.params.id, userId);
    return { status: 200, body: project };
  }

  // ── Task Handlers ──────────────────────────────────────────────────────────

  private listTasks(req: ApiRequest): ApiResponse {
    const { projectId } = req.query;
    const tasks = projectId
      ? this.taskService.getTasksByProject(projectId)
      : this.taskService.getAllTasks();
    return { status: 200, body: tasks };
  }

  private createTask(req: ApiRequest): ApiResponse {
    const data = req.body as {
      title?: string;
      description?: string;
      projectId?: string;
      assigneeId?: string | null;
    };

    if (!data?.projectId) {
      return { status: 400, body: { error: "projectId is required" } };
    }

    // Validate project exists
    if (!this.projectService.exists(data.projectId)) {
      return {
        status: 404,
        body: { error: `Project "${data.projectId}" not found` },
      };
    }

    // Validate assignee if provided
    if (data.assigneeId && !this.userService.exists(data.assigneeId)) {
      return {
        status: 404,
        body: { error: `User "${data.assigneeId}" not found` },
      };
    }

    const task = this.taskService.createTask({
      title: data?.title ?? "",
      description: data?.description,
      projectId: data.projectId,
      assigneeId: data?.assigneeId,
    });

    return { status: 201, body: task };
  }

  private getTask(req: ApiRequest): ApiResponse {
    const task = this.taskService.getTask(req.params.id);
    return { status: 200, body: task };
  }

  private updateTask(req: ApiRequest): ApiResponse {
    const data = req.body as Partial<{ title: string; description: string }>;
    const task = this.taskService.updateTask(req.params.id, data ?? {});
    return { status: 200, body: task };
  }

  private deleteTask(req: ApiRequest): ApiResponse {
    // Clean up comments before deleting
    this.commentService.deleteCommentsByTask(req.params.id);
    this.taskService.deleteTask(req.params.id);
    return { status: 200, body: { message: "Task deleted" } };
  }

  private changeTaskStatus(req: ApiRequest): ApiResponse {
    const data = req.body as { status?: string };
    const newStatus = data?.status as TaskStatus | undefined;

    if (!newStatus) {
      return { status: 400, body: { error: "status is required" } };
    }

    const validStatuses: TaskStatus[] = ["todo", "in-progress", "done"];
    if (!validStatuses.includes(newStatus)) {
      return {
        status: 400,
        body: {
          error: `Invalid status "${newStatus}". Must be one of: ${validStatuses.join(", ")}`,
        },
      };
    }

    const task = this.taskService.changeStatus(req.params.id, newStatus);
    return { status: 200, body: task };
  }

  private assignTask(req: ApiRequest): ApiResponse {
    const data = req.body as { assigneeId?: string };
    const assigneeId = data?.assigneeId;

    if (!assigneeId) {
      return { status: 400, body: { error: "assigneeId is required" } };
    }

    // Validate user exists
    if (!this.userService.exists(assigneeId)) {
      return { status: 404, body: { error: `User "${assigneeId}" not found` } };
    }

    const task = this.taskService.assignTask(req.params.id, assigneeId);
    return { status: 200, body: task };
  }

  // ── Comment Handlers ───────────────────────────────────────────────────────

  private listComments(req: ApiRequest): ApiResponse {
    const { taskId } = req.query;
    if (!taskId) {
      return { status: 400, body: { error: "taskId query parameter is required" } };
    }
    const comments = this.commentService.getCommentsByTask(taskId);
    return { status: 200, body: comments };
  }

  private createComment(req: ApiRequest): ApiResponse {
    const data = req.body as {
      taskId?: string;
      authorId?: string;
      body?: string;
    };

    if (!data?.taskId) {
      return { status: 400, body: { error: "taskId is required" } };
    }

    // Validate task exists and get its details for the event payload
    let task;
    try {
      task = this.taskService.getTask(data.taskId);
    } catch {
      return {
        status: 404,
        body: { error: `Task "${data.taskId}" not found` },
      };
    }

    // Validate author exists
    if (!data.authorId || !this.userService.exists(data.authorId)) {
      return {
        status: 404,
        body: { error: `User "${data.authorId}" not found` },
      };
    }

    const comment = this.commentService.createComment({
      taskId: data.taskId,
      authorId: data.authorId ?? "",
      body: data.body ?? "",
      taskTitle: task.title,
      assigneeId: task.assigneeId,
    });

    return { status: 201, body: comment };
  }

  private getComment(req: ApiRequest): ApiResponse {
    const comment = this.commentService.getComment(req.params.id);
    return { status: 200, body: comment };
  }

  private deleteComment(req: ApiRequest): ApiResponse {
    this.commentService.deleteComment(req.params.id);
    return { status: 200, body: { message: "Comment deleted" } };
  }

  // ── Notification Handlers ──────────────────────────────────────────────────

  private listNotifications(req: ApiRequest): ApiResponse {
    const { userId } = req.query;
    const notifications = userId
      ? this.notificationService.getNotificationsForUser(userId)
      : this.notificationService.getAllNotifications();
    return { status: 200, body: notifications };
  }

  private markNotificationRead(req: ApiRequest): ApiResponse {
    const notification = this.notificationService.markAsRead(req.params.id);
    return { status: 200, body: notification };
  }
}

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./user-service";
import { ProjectService } from "./project-service";
import { TaskService } from "./task-service";
import { CommentService } from "./comment-service";
import { NotificationService } from "./notification-service";
import { Router } from "./router";

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

/**
 * Wire up all services and start the HTTP server.
 *
 * Dependency order:
 *   1. EventBus  — no dependencies
 *   2. Services  — depend on EventBus
 *   3. Router    — depends on all services
 *   4. HTTP server — delegates to Router
 */
function bootstrap() {
  // 1. Event Bus
  const eventBus = new EventBus();

  // 2. Services
  const userService = new UserService();
  const projectService = new ProjectService(eventBus);
  const taskService = new TaskService(eventBus);
  const commentService = new CommentService(eventBus);
  // NotificationService registers its subscriptions in the constructor
  const notificationService = new NotificationService(eventBus);

  // 3. Router
  const router = new Router(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  // 4. HTTP Server
  const server = createServer((req, res) => {
    router.handle(req, res).catch((err: unknown) => {
      console.error("Unhandled error in router:", err);
      if (!res.headersSent) {
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "Internal server error" }));
      }
    });
  });

  server.listen(PORT, () => {
    console.log(`Task Management API listening on http://localhost:${PORT}`);
    console.log("Available routes:");
    console.log("  Users        : GET/POST /users, GET/PUT/DELETE /users/:id");
    console.log(
      "  Projects     : GET/POST /projects, GET/PUT/DELETE /projects/:id"
    );
    console.log("  Members      : POST/DELETE /projects/:id/members");
    console.log(
      "  Tasks        : GET/POST /tasks, GET/PUT/DELETE /tasks/:id"
    );
    console.log(
      "  Task actions : PUT /tasks/:id/status, PUT /tasks/:id/assign"
    );
    console.log("  Comments     : GET/POST /comments, GET/DELETE /comments/:id");
    console.log("  Notifications: GET /notifications, PUT /notifications/:id/read");
  });

  return server;
}

bootstrap();

/**
 * demo.ts
 *
 * Starts the Task Management API server and exercises every feature through
 * HTTP requests using only Node.js built-ins.
 *
 * Run with:  npx tsx src/demo.ts
 */

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./user-service";
import { ProjectService } from "./project-service";
import { TaskService } from "./task-service";
import { CommentService } from "./comment-service";
import { NotificationService } from "./notification-service";
import { Router } from "./router";

// ── Bootstrap (same as main.ts but inline so we can get the server ref) ───────

const DEMO_PORT = 3001;

const eventBus = new EventBus();
const userService = new UserService();
const projectService = new ProjectService(eventBus);
const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);
const notificationService = new NotificationService(eventBus);
const router = new Router(
  userService,
  projectService,
  taskService,
  commentService,
  notificationService
);

const server = createServer((req, res) => {
  router.handle(req, res).catch((err: unknown) => {
    console.error(err);
    if (!res.headersSent) {
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Internal server error" }));
    }
  });
});

// ── HTTP helper ───────────────────────────────────────────────────────────────

interface HttpResponse {
  status: number;
  body: unknown;
}

function request(
  method: string,
  path: string,
  body?: unknown
): Promise<HttpResponse> {
  return new Promise((resolve, reject) => {
    const payload = body !== undefined ? JSON.stringify(body) : undefined;
    const options = {
      hostname: "localhost",
      port: DEMO_PORT,
      path,
      method,
      headers: {
        "Content-Type": "application/json",
        ...(payload ? { "Content-Length": Buffer.byteLength(payload) } : {}),
      },
    };

    const req = require("http").request(options, (res: any) => {
      const chunks: Buffer[] = [];
      res.on("data", (chunk: Buffer) => chunks.push(chunk));
      res.on("end", () => {
        try {
          const parsed = JSON.parse(Buffer.concat(chunks).toString("utf-8"));
          resolve({ status: res.statusCode, body: parsed });
        } catch (e) {
          reject(e);
        }
      });
    });

    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

// ── Demo steps ─────────────────────────────────────────────────────────────────

function section(title: string) {
  console.log("\n" + "═".repeat(60));
  console.log(`  ${title}`);
  console.log("═".repeat(60));
}

function log(label: string, data: unknown) {
  console.log(`\n▶ ${label}`);
  console.log(JSON.stringify(data, null, 2));
}

async function runDemo() {
  section("1 · Create Users");

  const { body: alice } = await request("POST", "/users", {
    name: "Alice",
    email: "alice@example.com",
  });
  log("Created user Alice", alice);

  const { body: bob } = await request("POST", "/users", {
    name: "Bob",
    email: "bob@example.com",
  });
  log("Created user Bob", bob);

  const { body: carol } = await request("POST", "/users", {
    name: "Carol",
    email: "carol@example.com",
  });
  log("Created user Carol", carol);

  // List all users
  const { body: allUsers } = await request("GET", "/users");
  log("All users", allUsers);

  // Update a user
  const { body: updatedAlice } = await request(
    "PUT",
    `/users/${(alice as any).id}`,
    { name: "Alice Smith" }
  );
  log("Updated Alice's name", updatedAlice);

  // ── Projects ──────────────────────────────────────────────────────────────

  section("2 · Create Projects");

  const { body: project } = await request("POST", "/projects", {
    name: "Website Redesign",
    description: "Full redesign of the company website",
  });
  log("Created project", project);

  const { body: secondProject } = await request("POST", "/projects", {
    name: "Mobile App",
    description: "iOS and Android application",
  });
  log("Created second project", secondProject);

  // ── Members ───────────────────────────────────────────────────────────────

  section("3 · Add Project Members");

  const { body: projWithAlice } = await request(
    "POST",
    `/projects/${(project as any).id}/members`,
    { userId: (alice as any).id }
  );
  log("Added Alice to project (triggers member.added notification)", projWithAlice);

  const { body: projWithBob } = await request(
    "POST",
    `/projects/${(project as any).id}/members`,
    { userId: (bob as any).id }
  );
  log("Added Bob to project (triggers member.added notification)", projWithBob);

  // Remove Carol (who was never added — should error)
  const { status: removeBadStatus, body: removeErr } = await request(
    "DELETE",
    `/projects/${(project as any).id}/members`,
    { userId: (carol as any).id }
  );
  log(`Remove non-member Carol (expected error, got ${removeBadStatus})`, removeErr);

  // ── Tasks ─────────────────────────────────────────────────────────────────

  section("4 · Create Tasks");

  const { body: task1 } = await request("POST", "/tasks", {
    title: "Design mockups",
    description: "Create Figma mockups for all pages",
    projectId: (project as any).id,
    assigneeId: (alice as any).id,
  });
  log("Created task 1 (assigned to Alice → notifications fired)", task1);

  const { body: task2 } = await request("POST", "/tasks", {
    title: "Implement header",
    description: "HTML/CSS for the global header",
    projectId: (project as any).id,
  });
  log("Created task 2 (unassigned)", task2);

  const { body: task3 } = await request("POST", "/tasks", {
    title: "Write tests",
    description: "Unit and integration tests",
    projectId: (project as any).id,
    assigneeId: (bob as any).id,
  });
  log("Created task 3 (assigned to Bob → notifications fired)", task3);

  // List tasks for the project
  const { body: projectTasks } = await request(
    "GET",
    `/tasks?projectId=${(project as any).id}`
  );
  log("Tasks in project", projectTasks);

  // ── Task Assignment ───────────────────────────────────────────────────────

  section("5 · Assign Tasks");

  const { body: assignedTask2 } = await request(
    "PUT",
    `/tasks/${(task2 as any).id}/assign`,
    { assigneeId: (bob as any).id }
  );
  log("Assigned task 2 to Bob (triggers task.assigned notification)", assignedTask2);

  // Reassign task 1 to Carol
  const { body: reassignedTask1 } = await request(
    "PUT",
    `/tasks/${(task1 as any).id}/assign`,
    { assigneeId: (carol as any).id }
  );
  log("Reassigned task 1 to Carol (triggers task.assigned notification)", reassignedTask1);

  // ── Status Transitions ────────────────────────────────────────────────────

  section("6 · Task Status Transitions");

  const { body: task1InProgress } = await request(
    "PUT",
    `/tasks/${(task1 as any).id}/status`,
    { status: "in-progress" }
  );
  log("task1: todo → in-progress (triggers statusChanged notification)", task1InProgress);

  const { body: task1Done } = await request(
    "PUT",
    `/tasks/${(task1 as any).id}/status`,
    { status: "done" }
  );
  log("task1: in-progress → done (triggers statusChanged notification)", task1Done);

  // Invalid transition: done → todo
  const { status: badStatus, body: transitionErr } = await request(
    "PUT",
    `/tasks/${(task1 as any).id}/status`,
    { status: "todo" }
  );
  log(`Invalid transition done→todo (expected 500, got ${badStatus})`, transitionErr);

  // Move task2 forward
  const { body: task2InProgress } = await request(
    "PUT",
    `/tasks/${(task2 as any).id}/status`,
    { status: "in-progress" }
  );
  log("task2: todo → in-progress", task2InProgress);

  // ── Comments ──────────────────────────────────────────────────────────────

  section("7 · Comments");

  const { body: comment1 } = await request("POST", "/comments", {
    taskId: (task2 as any).id,
    authorId: (alice as any).id,
    body: "I have started on this. Should be done by Friday.",
  });
  log("Alice commented on task2 (Bob is assignee → notification to Bob)", comment1);

  const { body: comment2 } = await request("POST", "/comments", {
    taskId: (task2 as any).id,
    authorId: (bob as any).id,
    body: "Thanks Alice! Let me know if you need any help.",
  });
  log("Bob commented on his own task (no self-notification)", comment2);

  const { body: comment3 } = await request("POST", "/comments", {
    taskId: (task3 as any).id,
    authorId: (alice as any).id,
    body: "Please make sure to cover edge cases.",
  });
  log("Alice commented on task3 (Bob is assignee → notification to Bob)", comment3);

  // Fetch all comments for task2
  const { body: task2Comments } = await request(
    "GET",
    `/comments?taskId=${(task2 as any).id}`
  );
  log("All comments on task2", task2Comments);

  // Delete a comment
  const { body: deleteCommentResult } = await request(
    "DELETE",
    `/comments/${(comment3 as any).id}`
  );
  log("Deleted comment3", deleteCommentResult);

  // ── Notifications ─────────────────────────────────────────────────────────

  section("8 · Notifications");

  const { body: aliceNotifs } = await request(
    "GET",
    `/notifications?userId=${(alice as any).id}`
  );
  log("Alice's notifications", aliceNotifs);

  const { body: bobNotifs } = await request(
    "GET",
    `/notifications?userId=${(bob as any).id}`
  );
  log("Bob's notifications", bobNotifs);

  const { body: carolNotifs } = await request(
    "GET",
    `/notifications?userId=${(carol as any).id}`
  );
  log("Carol's notifications", carolNotifs);

  // Mark first notification of Bob as read
  if (Array.isArray(bobNotifs) && bobNotifs.length > 0) {
    const firstNotifId = (bobNotifs as any[])[0].id;
    const { body: readNotif } = await request(
      "PUT",
      `/notifications/${firstNotifId}/read`
    );
    log("Marked Bob's first notification as read", readNotif);
  }

  // All notifications (unfiltered)
  const { body: allNotifs } = await request("GET", "/notifications");
  log(`All notifications (${(allNotifs as any[]).length} total)`, allNotifs);

  // ── Update & Delete ───────────────────────────────────────────────────────

  section("9 · Update & Delete");

  const { body: updatedTask2 } = await request(
    "PUT",
    `/tasks/${(task2 as any).id}`,
    { title: "Implement responsive header", description: "Must work on mobile too" }
  );
  log("Updated task2 title and description", updatedTask2);

  const { body: updatedProject } = await request(
    "PUT",
    `/projects/${(project as any).id}`,
    { description: "Complete redesign — desktop and mobile" }
  );
  log("Updated project description", updatedProject);

  // Delete task3 (also deletes its comments)
  const { body: deleteTask3 } = await request(
    "DELETE",
    `/tasks/${(task3 as any).id}`
  );
  log("Deleted task3", deleteTask3);

  // Verify deletion
  const { status: missingTaskStatus, body: missingTask } = await request(
    "GET",
    `/tasks/${(task3 as any).id}`
  );
  log(`Fetch deleted task3 (expected 500, got ${missingTaskStatus})`, missingTask);

  // ── Error Cases ───────────────────────────────────────────────────────────

  section("10 · Error Cases");

  // Duplicate email
  const { status: dupStatus, body: dupErr } = await request("POST", "/users", {
    name: "Duplicate",
    email: "alice@example.com",
  });
  log(`Duplicate email (expected 500, got ${dupStatus})`, dupErr);

  // Non-existent user
  const { status: noUserStatus, body: noUserErr } = await request(
    "GET",
    "/users/does-not-exist"
  );
  log(`Non-existent user (expected 500, got ${noUserStatus})`, noUserErr);

  // Assign to non-existent user
  const { status: badAssignStatus, body: badAssignErr } = await request(
    "PUT",
    `/tasks/${(task2 as any).id}/assign`,
    { assigneeId: "ghost-user-id" }
  );
  log(`Assign to non-existent user (expected 404, got ${badAssignStatus})`, badAssignErr);

  // Unknown route
  const { status: notFoundStatus, body: notFoundErr } = await request(
    "GET",
    "/unknown/route"
  );
  log(`Unknown route (expected 404, got ${notFoundStatus})`, notFoundErr);

  section("Demo Complete ✓");
  console.log("\nAll features exercised successfully!\n");
}

// ── Entry point ───────────────────────────────────────────────────────────────

server.listen(DEMO_PORT, async () => {
  console.log(`Demo server started on http://localhost:${DEMO_PORT}`);
  try {
    await runDemo();
  } catch (err) {
    console.error("Demo failed:", err);
  } finally {
    server.close(() => {
      console.log("Demo server shut down.");
    });
  }
});

